1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23		ticketCancelled = "已取消"
24	
25		eventReport = "报修"
26		eventClose  = "关闭"
27		eventCancel = "取消"
28		eventAssign = "派工"
29	
30		storeVersion = 1
31		dataFileName = "caretrack.json"
32	)
33	
34	var (
35		errNotFound = errors.New("not found")
36		errConflict = errors.New("conflict")
37	)
38	
39	// Asset 为登记的设备资产，ID 即企业资产编号。
40	type Asset struct {
41		ID       string `json:"id"`
42		Name     string `json:"name"`
43		Location string `json:"location"`
44		Status   string `json:"status"`
45	}
46	
47	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
48	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
49	type Ticket struct {
50		ID           string `json:"id"`
51		AssetID      string `json:"asset_id"`
52		Description  string `json:"description"`
53		RequestID    string `json:"request_id"`
54		Status       string `json:"status"`
55		Result       string `json:"result,omitempty"`
56		CreatedAt    string `json:"created_at"`
57		ClosedAt     string `json:"closed_at,omitempty"`
58		CancelReason string `json:"cancel_reason,omitempty"`
59		CancelledAt  string `json:"cancelled_at,omitempty"`
60		Assignee     string `json:"assignee,omitempty"`
61		AssignedAt   string `json:"assigned_at,omitempty"`
62		AssignNote   string `json:"assign_note,omitempty"`
63	}
64	
65	// Event 为履历条目（报修/派工/关闭/取消），Seq 决定操作发生顺序。
66	// From/To 仅派工履历使用：原负责人（首次派工为空，展示为“未派工”）与新负责人。
67	type Event struct {
68		Seq      int       `json:"-"`
69		AssetID  string    `json:"-"`
70		TicketID string    `json:"-"`
71		Kind     string    `json:"-"`
72		Content  string    `json:"-"`
73		From     string    `json:"-"`
74		To       string    `json:"-"`
75		Time     time.Time `json:"-"`
76	}
77	
78	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
79	type eventJSON struct {
80		Seq      int    `json:"seq"`
81		AssetID  string `json:"asset_id"`
82		TicketID string `json:"ticket_id"`
83		Kind     string `json:"kind"`
84		Content  string `json:"content"`
85		From     string `json:"from,omitempty"`
86		To       string `json:"to,omitempty"`
87		Time     string `json:"time"`
88	}
89	
90	func (e Event) toJSON() eventJSON {
91		return eventJSON{
92			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
93			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
94			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
95			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
96			// 在重新保存（含导入合并后的提交）时也不会被截断。
97			Time: e.Time.Format(time.RFC3339Nano),
98		}
99	}
100	
101	func (e eventJSON) toEvent() (Event, error) {
102		t, err := time.Parse(time.RFC3339, e.Time)
103		if err != nil {
104			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
105		}
106		return Event{
107			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
108			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To, Time: t,
109		}, nil
110	}
111	
112	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
113	// 它既不是资产编号也不是工单编号。
114	type requestBinding struct {
115		RequestID   string `json:"request_id"`
116		AssetID     string `json:"asset_id"`
117		Description string `json:"description"`
118		TicketID    string `json:"ticket_id"`
119	}
120	
121	// storeData 是一次成功写操作共同生效的完整业务数据。
122	type storeData struct {
123		Version       int              `json:"version"`
124		Assets        []*Asset         `json:"assets"`
125		Tickets       []*Ticket        `json:"tickets"`
126		Events        []Event          `json:"-"`
127		EventsJSON    []eventJSON      `json:"events"`
128		Requests      []requestBinding `json:"requests"`
129		NextTicketSeq int              `json:"next_ticket_seq"`
130	}
131	
132	type store struct {
133		dir  string
134		data *storeData
135		now  func() time.Time
136	}
137	
138	func newStoreData() *storeData {
139		return &storeData{
140			Version:       storeVersion,
141			Assets:        []*Asset{},
142			Tickets:       []*Ticket{},
143			Events:        []Event{},
144			EventsJSON:    []eventJSON{},
145			Requests:      []requestBinding{},
146			NextTicketSeq: 1,
147		}
148	}
149	
150	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
151	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
152	func openStore(dir string) (*store, error) {
153		return loadStore(dir, true)
154	}
155	
156	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
157	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
158	func openSourceStore(dir string) (*store, error) {
159		return loadStore(dir, false)
160	}
161	
162	func loadStore(dir string, allowMissing bool) (*store, error) {
163		path := filepath.Join(dir, dataFileName)
164		raw, err := os.ReadFile(path)
165		if err != nil {
166			if errors.Is(err, os.ErrNotExist) {
167				if allowMissing {
168					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
169				}
170				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
171			}
172			return nil, fmt.Errorf("读取数据文件失败: %w", err)
173		}
174		if len(bytes.TrimSpace(raw)) == 0 {
175			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
176		}
177		var d storeData
178		if err := json.Unmarshal(raw, &d); err != nil {
179			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
180		}
181		if d.EventsJSON != nil {
182			d.Events = make([]Event, len(d.EventsJSON))
183			for i, ej := range d.EventsJSON {
184				ev, err := ej.toEvent()
185				if err != nil {
186					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
187				}
188				d.Events[i] = ev
189			}
190		}
191		if err := validateData(&d); err != nil {
192			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
193		}
194		return &store{dir: dir, data: &d, now: time.Now}, nil
195	}
196	
197	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
198	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
199	func parseTicketSeq(id string) (int, bool) {
200		if !strings.HasPrefix(id, "T") {
201			return 0, false
202		}
203		n, err := strconv.Atoi(id[1:])
204		if err != nil || n < 1 {
205			return 0, false
206		}
207		if fmt.Sprintf("T%04d", n) != id {
208			return 0, false
209		}
210		return n, true
211	}
212	
213	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
214	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
215	// 不做任何修复：不补字段、不重编号、不删除记录。
216	func validateData(d *storeData) error {
217		if d.Version != storeVersion {
218			return fmt.Errorf("不支持的数据版本 %d", d.Version)
219		}
220		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil {
221			return errors.New("缺少必要的数据段")
222		}
223		assets := map[string]*Asset{}
224		for _, a := range d.Assets {
225			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
226				return errors.New("数据矛盾：存在字段不完整的资产记录")
227			}
228			if a.Status != statusAvailable && a.Status != statusRepairing {
229				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
230			}
231			if assets[a.ID] != nil {
232				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
233			}
234			assets[a.ID] = a
235		}
236		tickets := map[string]*Ticket{}
237		maxTicketSeq := 0
238		for _, t := range d.Tickets {
239			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
240				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
241			}
242			n, ok := parseTicketSeq(t.ID)
243			if !ok {
244				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
245			}
246			if n > maxTicketSeq {
247				maxTicketSeq = n
248			}
249			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
250				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
251			}
252			if assets[t.AssetID] == nil {
253				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
254			}
255			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
256				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
257			}
258			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
259				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
260			}
261			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
262				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
263			}
264			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
265				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
266			}
267			if t.Assignee == "" {
268				if t.AssignedAt != "" || t.AssignNote != "" {
269					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
270				}
271			} else if t.AssignedAt == "" || t.AssignNote == "" {
272				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
273			}
274			if tickets[t.ID] != nil {
275				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
276			}
277			tickets[t.ID] = t
278		}
279		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
280		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
281			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
282				d.NextTicketSeq, maxTicketSeq)
283		}
284		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
285		boundReq := map[string]bool{}
286		boundTicket := map[string]bool{}
287		for _, r := range d.Requests {
288			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
289				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
290			}
291			if boundReq[r.RequestID] {
292				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
293			}
294			boundReq[r.RequestID] = true
295			t := tickets[r.TicketID]
296			if t == nil {
297				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
298			}
299			if t.RequestID != r.RequestID {
300				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
301					r.TicketID, t.RequestID, r.RequestID)
302			}
303			if r.AssetID != t.AssetID || r.Description != t.Description {
304				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
305					r.RequestID, t.ID)
306			}
307			boundTicket[r.TicketID] = true
308		}
309		for _, t := range d.Tickets {
310			if !boundTicket[t.ID] {
311				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
312			}
313		}
314		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
315		openCount := map[string]int{}
316		for _, t := range d.Tickets {
317			if t.Status == ticketOpen {
318				openCount[t.AssetID]++
319			}
320		}
321		for _, a := range d.Assets {
322			c := openCount[a.ID]
323			if c > 1 {
324				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
325			}
326			want := statusAvailable
327			if c == 1 {
328				want = statusRepairing
329			}
330			if a.Status != want {
331				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
332					a.ID, c, want, a.Status)
333			}
334		}
335		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
336		seenSeq := map[int]bool{}
337		reportSeq := map[string]int{}
338		closeSeq := map[string]int{}
339		cancelSeq := map[string]int{}
340		reportCount := map[string]int{}
341		closeCount := map[string]int{}
342		cancelCount := map[string]int{}
343		for i := range d.Events {
344			e := &d.Events[i]
345			if e.Seq < 1 {
346				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
347			}
348			if seenSeq[e.Seq] {
349				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
350			}
351			seenSeq[e.Seq] = true
352			if e.AssetID == "" || e.TicketID == "" || e.Kind == "" || e.Content == "" {
353				return errors.New("履历矛盾：存在字段不完整的履历记录")
354			}
355			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
356				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
357			}
358			if e.Kind == eventAssign {
359				if e.To == "" {
360					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
361				}
362				if e.From == e.To {
363					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
364				}
365			}
366			t := tickets[e.TicketID]
367			if t == nil || assets[e.AssetID] == nil {
368				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
369			}
370			if e.AssetID != t.AssetID {
371				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
372					e.Seq, e.AssetID, t.ID, t.AssetID)
373			}
374			switch e.Kind {
375			case eventReport:
376				if e.Content != t.Description {
377					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
378				}
379				reportCount[t.ID]++
380				reportSeq[t.ID] = e.Seq
381			case eventClose:
382				if e.Content != t.Result {
383					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
384				}
385				closeCount[t.ID]++
386				closeSeq[t.ID] = e.Seq
387			case eventCancel:
388				if e.Content != t.CancelReason {
389					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
390				}
391				cancelCount[t.ID]++
392				cancelSeq[t.ID] = e.Seq
393			case eventAssign:
394				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
395				// 在下方按序号重放时核对。
396			default:
397				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
398			}
399		}
400		for _, t := range d.Tickets {
401			if reportCount[t.ID] != 1 {
402				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
403			}
404			if t.Status == ticketClosed {
405				if closeCount[t.ID] != 1 {
406					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
407				}
408				if closeSeq[t.ID] <= reportSeq[t.ID] {
409					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
410						t.ID, closeSeq[t.ID], reportSeq[t.ID])
411				}
412			} else if closeCount[t.ID] != 0 {
413				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
414			}
415			if t.Status == ticketCancelled {
416				if cancelCount[t.ID] != 1 {
417					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
418				}
419				if cancelSeq[t.ID] <= reportSeq[t.ID] {
420					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
421						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
422				}
423			} else if cancelCount[t.ID] != 0 {
424				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
425			}
426		}
427		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
428		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
429		sorted := make([]Event, len(d.Events))
430		copy(sorted, d.Events)
431		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
432		derivedTicket := map[string]string{}
433		derivedOpen := map[string]string{}
434		derivedAssignee := map[string]string{}
435		derivedNote := map[string]string{}
436		for _, e := range sorted {
437			switch e.Kind {
438			case eventReport:
439				if derivedTicket[e.TicketID] != "" {
440					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
441				}
442				if prev := derivedOpen[e.AssetID]; prev != "" {
443					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
444						e.AssetID, prev, e.TicketID)
445				}
446				derivedTicket[e.TicketID] = ticketOpen
447				derivedOpen[e.AssetID] = e.TicketID
448			case eventAssign:
449				if derivedTicket[e.TicketID] != ticketOpen {
450					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
451				}
452				if e.From != derivedAssignee[e.TicketID] {
453					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
454						e.TicketID, e.Seq, e.From)
455				}
456				derivedAssignee[e.TicketID] = e.To
457				derivedNote[e.TicketID] = e.Content
458			case eventClose:
459				if derivedTicket[e.TicketID] != ticketOpen {
460					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
461				}
462				derivedTicket[e.TicketID] = ticketClosed
463				delete(derivedOpen, e.AssetID)
464			case eventCancel:
465				if derivedTicket[e.TicketID] != ticketOpen {
466					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
467				}
468				derivedTicket[e.TicketID] = ticketCancelled
469				delete(derivedOpen, e.AssetID)
470			}
471		}
472		for _, t := range d.Tickets {
473			if derivedTicket[t.ID] != t.Status {
474				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
475					t.ID, derivedTicket[t.ID], t.Status)
476			}
477			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
478			if derivedAssignee[t.ID] != t.Assignee {
479				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
480					t.ID, derivedAssignee[t.ID], t.Assignee)
481			}
482			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
483				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
484			}
485		}
486		for _, a := range d.Assets {
487			want := statusAvailable
488			if derivedOpen[a.ID] != "" {
489				want = statusRepairing
490			}
491			if a.Status != want {
492				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
493					a.ID, want, a.Status)
494			}
495		}
496		return nil
497	}
498	
499	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
500	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
501	// 保持不变，不留下部分业务变化。
502	func (s *store) save() error {
503		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
504		for i, e := range s.data.Events {
505			s.data.EventsJSON[i] = e.toJSON()
506		}
507		if err := validateData(s.data); err != nil {
508			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
509		}
510		var buf bytes.Buffer
511		enc := json.NewEncoder(&buf)
512		enc.SetIndent("", "  ")
513		if err := enc.Encode(s.data); err != nil {
514			return fmt.Errorf("编码数据失败: %w", err)
515		}
516		if err := os.MkdirAll(s.dir, 0o755); err != nil {
517			return fmt.Errorf("创建数据目录失败: %w", err)
518		}
519		path := filepath.Join(s.dir, dataFileName)
520		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
521		if err != nil {
522			return fmt.Errorf("创建临时数据文件失败: %w", err)
523		}
524		tmpName := tmp.Name()
525		abort := func(err error) error {
526			_ = tmp.Close()
527			_ = os.Remove(tmpName)
528			return err
529		}
530		if _, err := tmp.Write(buf.Bytes()); err != nil {
531			abort(nil)
532			return fmt.Errorf("写入数据失败: %w", err)
533		}
534		if err := tmp.Sync(); err != nil {
535			abort(nil)
536			return fmt.Errorf("写入数据失败: %w", err)
537		}
538		if err := tmp.Close(); err != nil {
539			_ = os.Remove(tmpName)
540			return fmt.Errorf("写入数据失败: %w", err)
541		}
542		if err := os.Rename(tmpName, path); err != nil {
543			_ = os.Remove(tmpName)
544			return fmt.Errorf("保存数据失败: %w", err)
545		}
546		return nil
547	}
548	
549	func (s *store) findAsset(id string) *Asset {
550		for _, a := range s.data.Assets {
551			if a.ID == id {
552				return a
553			}
554		}
555		return nil
556	}
557	
558	func (s *store) findTicket(id string) *Ticket {
559		for _, t := range s.data.Tickets {
560			if t.ID == id {
561				return t
562			}
563		}
564		return nil
565	}
566	
567	func (s *store) findRequest(requestID string) *requestBinding {
568		for i := range s.data.Requests {
569			if s.data.Requests[i].RequestID == requestID {
570				return &s.data.Requests[i]
571			}
572		}
573		return nil
574	}
575	
576	func (s *store) openTicketOf(assetID string) *Ticket {
577		for _, t := range s.data.Tickets {
578			if t.AssetID == assetID && t.Status == ticketOpen {
579				return t
580			}
581		}
582		return nil
583	}
584	
585	func (s *store) eventsOf(assetID string) []Event {
586		out := make([]Event, 0)
587		for _, e := range s.data.Events {
588			if e.AssetID == assetID {
589				out = append(out, e)
590			}
591		}
592		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
593		return out
594	}
595	
596	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
597	func (s *store) nextEventSeq() (int, error) {
598		maxSeq := 0
599		for _, e := range s.data.Events {
600			if e.Seq > maxSeq {
601				maxSeq = e.Seq
602			}
603		}
604		if maxSeq == math.MaxInt {
605			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
606		}
607		return maxSeq + 1, nil
608	}
609	
610	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
611	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
612	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
613		s.data.Events = append(s.data.Events, Event{
614			Seq:      seq,
615			AssetID:  assetID,
616			TicketID: ticketID,
617			Kind:     kind,
618			Content:  content,
619			From:     from,
620			To:       to,
621			Time:     s.now(),
622		})
623	}
624	
625	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
626		if s.findAsset(id) != nil {
627			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
628		}
629		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
630		s.data.Assets = append(s.data.Assets, a)
631		return a, nil
632	}
633	
634	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
635	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
636	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
637		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
638		// 资产或描述不同 => 拒绝。
639		if r := s.findRequest(requestID); r != nil {
640			if r.AssetID != assetID || r.Description != description {
641				return nil, false, fmt.Errorf(
642					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
643					errConflict, requestID, r.AssetID)
644			}
645			t := s.findTicket(r.TicketID)
646			if t == nil {
647				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
648			}
649			return t, true, nil
650		}
651	
652		asset := s.findAsset(assetID)
653		if asset == nil {
654			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
655		}
656		if t := s.openTicketOf(assetID); t != nil {
657			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
658		}
659		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
660		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
661		seq := s.data.NextTicketSeq
662		if seq < 1 || seq == math.MaxInt {
663			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
664		}
665		eventSeq, err := s.nextEventSeq()
666		if err != nil {
667			return nil, false, err
668		}
669		t := &Ticket{
670			ID:          fmt.Sprintf("T%04d", seq),
671			AssetID:     assetID,
672			Description: description,
673			RequestID:   requestID,
674			Status:      ticketOpen,
675			CreatedAt:   s.now().Format(time.RFC3339),
676		}
677		s.data.NextTicketSeq = seq + 1
678		s.data.Tickets = append(s.data.Tickets, t)
679		s.data.Requests = append(s.data.Requests, requestBinding{
680			RequestID:   requestID,
681			AssetID:     assetID,
682			Description: description,
683			TicketID:    t.ID,
684		})
685		asset.Status = statusRepairing
686		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
687		return t, false, nil
688	}
689	
690	// closeTicket 关闭未关闭工单并把资产恢复为可用。
691	// 失败路径不修改任何业务数据。
692	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
693		t := s.findTicket(ticketID)
694		if t == nil {
695			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
696		}
697		if t.Status == ticketCancelled {
698			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
699		}
700		if t.Status != ticketOpen {
701			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
702		}
703		asset := s.findAsset(t.AssetID)
704		if asset == nil {
705			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
706		}
707		eventSeq, err := s.nextEventSeq()
708		if err != nil {
709			return nil, nil, err
710		}
711		t.Status = ticketClosed
712		t.Result = result
713		t.ClosedAt = s.now().Format(time.RFC3339)
714		asset.Status = statusAvailable
715		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
716		return t, asset, nil
717	}
718	
719	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
720	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
721	// 失败路径不修改任何业务数据。
722	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
723		t := s.findTicket(ticketID)
724		if t == nil {
725			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
726		}
727		if t.Status == ticketCancelled {
728			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
729		}
730		if t.Status == ticketClosed {
731			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
732		}
733		asset := s.findAsset(t.AssetID)
734		if asset == nil {
735			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
736		}
737		eventSeq, err := s.nextEventSeq()
738		if err != nil {
739			return nil, nil, err
740		}
741		t.Status = ticketCancelled
742		t.CancelReason = reason
743		t.CancelledAt = s.now().Format(time.RFC3339)
744		asset.Status = statusAvailable
745		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
746		return t, asset, nil
747	}
748	
749	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
750	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
751	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
752	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
753	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
754	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
755		t := s.findTicket(ticketID)
756		if t == nil {
757			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
758		}
759		if t.Status == ticketClosed {
760			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
761		}
762		if t.Status == ticketCancelled {
763			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
764		}
765		if assignee == "" {
766			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
767		}
768		if note == "" {
769			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
770		}
771		if t.Assignee == assignee {
772			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
773				errConflict, ticketID, assignee)
774		}
775		eventSeq, err := s.nextEventSeq()
776		if err != nil {
777			return nil, err
778		}
779		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
780		t.Assignee = assignee
781		t.AssignedAt = s.now().Format(time.RFC3339)
782		t.AssignNote = note
783		return t, nil
784	}
