13	const appName = "caretrack"
14	
15	const helpText = `caretrack — 本地设备资产登记与维修工单闭环工具
16	
17	数据保存在本地目录，无外部服务依赖，仅支持单进程顺序调用。
18	
19	用法:
20	  caretrack <命令> [参数]
21	
22	命令:
23	  register   登记资产（企业资产编号、名称、位置）
24	  list       列出全部资产及当前状态
25	  detail     查看资产详情及其未关闭工单编号
26	  report     对资产报修，创建工单，资产转为“维修中”
27	  assign     为未关闭工单派工或转派维修人员
28	  ticket     按工单编号查询工单状态与负责人
29	  close      关闭工单并填写维修结果，设备恢复“可用”
30	  cancel     取消误报或不再需要维修的未关闭工单，设备恢复“可用”
31	  history    按资产查看维修履历（报修、派工、关闭、取消事件）
32	  downtime   查询时间窗口内的设备维修停机时长（单项或全部资产）
33	  import     从另一数据目录批量导入资产及其工单、履历与请求绑定（复制，源只读）
34	  help       显示本帮助
35	
36	各命令参数:
37	  register --asset-id 编号 --name 名称 --location 位置 [--data-dir 目录]
38	  list                                                        [--data-dir 目录]
39	  detail   --asset-id 编号                                    [--data-dir 目录]
40	  report   --asset-id 编号 --description 故障描述 --request-id 请求标识
41	                                                              [--data-dir 目录]
42	  assign   --ticket-id 工单编号 --assignee 维修人员 --note 说明  [--data-dir 目录]
43	  ticket   --ticket-id 工单编号                                 [--data-dir 目录]
44	  close    --ticket-id 工单编号 --repair-result 维修结果       [--data-dir 目录]
45	  cancel   --ticket-id 工单编号 --reason 取消理由              [--data-dir 目录]
46	  history  --asset-id 编号                                    [--data-dir 目录]
47	  downtime --start 起点 --end 终点 [--asset-id 编号]          [--data-dir 目录]
48	  import   --source-dir 源目录 --asset-id 编号 [--asset-id 编号...]
49	                                                              [--data-dir 目录]
50	
51	通用参数:
52	  --data-dir 目录   本地数据目录，默认 ".caretrack"；不同目录数据互不影响，
53	                    目录不存在时会在首次成功写入时自动初始化
54	
55	业务规则:
56	  - 资产编号、名称、位置均不能为空；同一数据目录内资产编号唯一，新资产为“可用”。
57	  - 每项资产最多有一张未关闭工单；未知资产、空故障描述、资产已有未关闭工单时
58	    报修失败，不改变状态与履历。
59	  - --request-id 由调用方提供且非空，仅用于同一数据目录内的报修去重，不作为
60	    资产或工单编号：相同标识、资产、描述再次提交返回原工单及当前状态，不新增
61	    记录；同一标识搭配不同资产或描述将被拒绝；原工单关闭或取消后重放仍返回原工单，
62	    不重开旧单，也不影响新单。
63	  - 仅未关闭工单可派工：没有负责人时首次派工，已有负责人时转派给不同人员。
64	    维修人员标识只是本地文本记录（非人员账户），与派工说明均不能为空；
65	    成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为
66	    “未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单编号，
67	    不改变资产状态或报修请求绑定；未知工单、空人员或说明、重复派给当前
68	    人员、对已关闭或已取消工单派工均失败且不产生履历。工单关闭或取消后
69	    保留最后负责人与派工履历。
70	  - 仅未关闭工单可关闭，维修结果不能为空；未知工单、重复关闭均失败。
71	  - 仅未关闭工单可取消，取消理由不能为空；取消后工单进入“已取消”终态，保存取消
72	    理由与时间，资产恢复“可用”，可再次报修。取消不代表维修完成，不填写维修结果，
73	    不删除工单、履历或请求绑定，工单编号不回退也不复用；已取消工单不能关闭或再次
74	    取消，已关闭工单也不能取消。
75	  - downtime 为只读统计，不写文件、不初始化目录、不追加履历。--start/--end 为
76	    带时区的 RFC3339 时刻（可含小数秒），起点须早于终点；窗口包含起点、不包含
77	    终点，按实际时刻比较。停机自工单报修履历时间起，至关闭或取消履历时间止
78	    （取消前的占用同样计入）；派工、转派不另起区间；未关闭工单暂算到窗口终点，
79	    不读取运行时刻，也不改变状态。只统计工单区间与窗口的交集，窗口外及零长度
80	    不贡献；同一资产多张工单的重叠交集取并集，不直接相加。每项资产合计后向下
81	    取整为秒，并输出全部所选资产秒数之和；没有停机的资产显示零。不给 --asset-id
82	    时统计全部资产并按编号字典序排列，空库明确提示无记录并显示零合计。若所选
83	    资产任一终结工单的结束履历时间早于报修履历时间（即使该单在窗口外、结束
84	    等于开始合法），整次统计失败，指出资产与工单，不输出部分结果。
85	  - import 把源数据目录中所选资产连同全部工单、报修请求绑定与履历复制到目标
86	    目录（--data-dir）：源台账始终只读，同一台账不能导入自身；重复编号按一项
87	    处理。工单编号按源工单序号升序从目标下一序号重新分配，履历与请求绑定中的
88	    工单引用同步替换；履历在目标最大履历序号之后按源序号顺序分配新序号，保留
89	    原操作顺序与原时间（含小数秒）。资产编号在目标已存在、或所选工单的任一
90	    请求标识已在目标绑定时整批拒绝，不覆盖、不合并。导入后可用原请求标识、
91	    资产与描述重放报修，返回映射后的工单及其当前状态；再次导入同一批资产按
92	    编号冲突拒绝。任何失败（源不存在、资产不存在、台账损坏、编号或履历序号
93	    容量不足、读写失败）都整批失败，两边原文件不变，不消耗目标编号。
94	
95	无参数、--help、-h 显示本帮助；参数错误或业务失败以非零退出码结束并说明原因。
96	参数错误退出码为 2；未知资产、上述时间异常及数据读取失败退出码为 1。
97	`
98	
99	type cmdOptions struct {
100		dataDir string
101	}
102	
103	func printHelp(w io.Writer) {
104		fmt.Fprint(w, helpText)
105	}
106	
107	func main() {
108		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
109	}
110	
111	func run(args []string, stdout, stderr io.Writer) int {
112		if len(args) == 0 {
113			printHelp(stdout)
114			return 0
115		}
116		switch args[0] {
117		case "--help", "-h", "help":
118			if len(args) > 1 {
119				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
120				return 2
121			}
122			printHelp(stdout)
123			return 0
124		}
125	
126		var err error
127		switch args[0] {
128		case "register":
129			err = cmdRegister(args[1:], stdout)
130		case "list":
131			err = cmdList(args[1:], stdout)
132		case "detail":
133			err = cmdDetail(args[1:], stdout)
134		case "report":
135			err = cmdReport(args[1:], stdout)
136		case "assign":
137			err = cmdAssign(args[1:], stdout)
138		case "ticket":
139			err = cmdTicket(args[1:], stdout)
140		case "close":
141			err = cmdClose(args[1:], stdout)
142		case "cancel":
143			err = cmdCancel(args[1:], stdout)
144		case "history":
145			err = cmdHistory(args[1:], stdout)
146		case "downtime":
147			err = cmdDowntime(args[1:], stdout)
148		case "import":
149			err = cmdImport(args[1:], stdout)
150		default:
151			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
152			return 2
153		}
154		if err != nil {
155			if errors.Is(err, flag.ErrHelp) {
156				return 0
157			}
158			var ue *usageError
159			if errors.As(err, &ue) {
160				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
161				return 2
162			}
163			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
164			return 1
165		}
166		return 0
167	}
168	
169	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
170	func friendlyErr(msg string) string {
171		for _, p := range []string{"not found: ", "conflict: "} {
172			if strings.HasPrefix(msg, p) {
173				return msg[len(p):]
174			}
175		}
176		return msg
177	}
178	
179	type usageError struct{ msg string }
180	
181	func (e *usageError) Error() string { return e.msg }
182	
183	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
184	// 其余参数错误转成 *usageError（退出码 2）。
185	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
186		fs := flag.NewFlagSet(name, flag.ContinueOnError)
187		fs.SetOutput(os.Stdout)
188		fs.Usage = func() {
189			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
190			fs.PrintDefaults()
191		}
192		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
193		return fs
194	}
195	
196	func parseFlags(fs *flag.FlagSet, args []string) error {
197		if err := fs.Parse(args); err != nil {
198			if errors.Is(err, flag.ErrHelp) {
199				return err
200			}
201			return &usageError{msg: err.Error()}
202		}
203		if fs.NArg() > 0 {
204			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
205		}
206		return nil
207	}
208	
209	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
210		if value == "" {
211			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
212		}
213		return nil
214	}
215	
216	func cmdRegister(args []string, w io.Writer) error {
217		var opts cmdOptions
218		var id, name, location string
219		fs := newFlagSet("register", &opts)
220		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
221		fs.StringVar(&name, "name", "", "资产名称（必填）")
222		fs.StringVar(&location, "location", "", "资产位置（必填）")
223		if err := parseFlags(fs, args); err != nil {
224			return err
225		}
226		if err := requireFlag(fs, id, "asset-id"); err != nil {
227			return err
228		}
229		if err := requireFlag(fs, name, "name"); err != nil {
230			return err
231		}
232		if err := requireFlag(fs, location, "location"); err != nil {
233			return err
234		}
235	
236		s, err := openStore(opts.dataDir)
237		if err != nil {
238			return err
239		}
240		asset, err := s.registerAsset(id, name, location)
241		if err != nil {
242			return err
243		}
244		if err := s.save(); err != nil {
245			return err
246		}
247		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
248		fmt.Fprintf(w, "名称: %s\n", asset.Name)
249		fmt.Fprintf(w, "位置: %s\n", asset.Location)
250		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
251		return nil
252	}
253	
254	func cmdList(args []string, w io.Writer) error {
255		var opts cmdOptions
256		fs := newFlagSet("list", &opts)
257		if err := parseFlags(fs, args); err != nil {
258			return err
259		}
260		s, err := openStore(opts.dataDir)
261		if err != nil {
262			return err
263		}
264		assets := s.data.Assets
265		if len(assets) == 0 {
266			fmt.Fprintln(w, "没有记录。")
267			return nil
268		}
269		fmt.Fprintf(w, "共 %d 项资产:\n", len(assets))
270		for _, a := range assets {
271			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
272		}
273		return nil
274	}
275	
276	func cmdDetail(args []string, w io.Writer) error {
277		var opts cmdOptions
278		var id string
279		fs := newFlagSet("detail", &opts)
280		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
281		if err := parseFlags(fs, args); err != nil {
