491	func cmdHistory(args []string, w io.Writer) error {
492		var opts cmdOptions
493		var id string
494		fs := newFlagSet("history", &opts)
495		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
496		if err := parseFlags(fs, args); err != nil {
497			return err
498		}
499		if err := requireFlag(fs, id, "asset-id"); err != nil {
500			return err
501		}
502		s, err := openStore(opts.dataDir)
503		if err != nil {
504			return err
505		}
506		if s.findAsset(id) == nil {
507			return fmt.Errorf("未知资产编号 %q", id)
508		}
509		events := s.eventsOf(id)
510		if len(events) == 0 {
511			fmt.Fprintf(w, "资产 %s 暂无维修履历。\n", id)
512			return nil
513		}
514		fmt.Fprintf(w, "资产 %s 维修履历（共 %d 条）:\n", id, len(events))
515		for _, e := range events {
516			if e.Kind == eventAssign {
517				fmt.Fprintf(w, "[%s] %s 工单 %s: %s -> %s（%s）\n",
518					e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID,
519					assigneeDisplay(e.From), e.To, e.Content)
520				continue
521			}
522			fmt.Fprintf(w, "[%s] %s 工单 %s: %s\n",
523				e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID, e.Content)
524		}
525		return nil
526	}
527	
528	// cmdDowntime 为只读的停机时长统计：先经 openStore 完成整库一致性检查，
529	// 再计算窗口内的停机秒数。无论成功或失败都不保存，因此不写文件、不初始化
530	// 目录、不追加履历、不消耗编号，也不改变报修请求绑定。
531	func cmdDowntime(args []string, w io.Writer) error {
532		var opts cmdOptions
533		var startText, endText, assetID string
534		fs := newFlagSet("downtime", &opts)
535		fs.StringVar(&startText, "start", "", "窗口起点（必填，带时区的 RFC3339 时刻，可含小数秒；包含）")
536		fs.StringVar(&endText, "end", "", "窗口终点（必填，带时区的 RFC3339 时刻，可含小数秒；不包含）")
537		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（可选；缺省统计全部资产）")
538		if err := parseFlags(fs, args); err != nil {
539			return err
540		}
541		if err := requireFlag(fs, startText, "start"); err != nil {
542			return err
543		}
544		if err := requireFlag(fs, endText, "end"); err != nil {
545			return err
546		}
547		start, err := time.Parse(time.RFC3339, startText)
548		if err != nil {
549			return &usageError{msg: fmt.Sprintf("--start 不是带时区的 RFC3339 时刻 %q: %s", startText, err)}
550		}
551		end, err := time.Parse(time.RFC3339, endText)
552		if err != nil {
553			return &usageError{msg: fmt.Sprintf("--end 不是带时区的 RFC3339 时刻 %q: %s", endText, err)}
554		}
555		if !start.Before(end) {
556			return &usageError{msg: fmt.Sprintf("--start（%s）须早于 --end（%s）", startText, endText)}
557		}
558	
559		// openStore 已先做整库一致性检查：损坏或关联矛盾按原规则拒绝（退出码 1）。
560		s, err := openStore(opts.dataDir)
561		if err != nil {
562			return err
563		}
564	
565		var ids []string
566		if assetID != "" {
567			// 未知资产在统计前拒绝（退出码 1）。
568			if s.findAsset(assetID) == nil {
569				return fmt.Errorf("未知资产编号 %q", assetID)
570			}
571			ids = []string{assetID}
572		} else {
573			ids = s.allAssetIDs()
574			if len(ids) == 0 {
575				fmt.Fprintln(w, "没有记录。")
576				fmt.Fprintln(w, "合计: 0 秒")
577				return nil
578			}
579		}
580	
581		// 先算完全部结果再输出：任一资产存在时间异常时整体失败，不输出部分结果。
582		results, err := s.downtimeForAssets(ids, start, end)
583		if err != nil {
584			return err
585		}
586		var total int64
587		if len(results) == 1 {
588			r := results[0]
589			fmt.Fprintf(w, "资产编号: %s\n", r.AssetID)
590			fmt.Fprintf(w, "名称: %s\n", r.Name)
591			fmt.Fprintf(w, "停机秒数: %d\n", r.Seconds)
592			total = r.Seconds
593		} else {
594			fmt.Fprintf(w, "共 %d 项资产:\n", len(results))
595			for _, r := range results {
596				fmt.Fprintf(w, "%s\t%s\t%d\n", r.AssetID, r.Name, r.Seconds)
597				total += r.Seconds
598			}
599		}
600		fmt.Fprintf(w, "合计: %d 秒\n", total)
601		return nil
602	}
603

