14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定与
15	// 报修/派工/关闭/取消履历复制到目标数据目录。
16	//
17	// 关键规则：
18	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
19	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
20	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
21	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
22	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
23	//     或其他业务事件。
24	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
25	//     不覆盖、不合并、不改请求标识。
26	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
27	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
28	
29	// stringListFlag 收集可重复的 --asset-id 参数。
30	type stringListFlag []string
31	
32	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
33	
34	func (f *stringListFlag) Set(v string) error {
35		*f = append(*f, v)
36		return nil
37	}
38	
39	// ticketRemap 记录一张工单的原编号与新编号。
40	type ticketRemap struct {
41		OldID string
42		NewID string
43	}
44	
45	// importOutcome 为一次成功导入的结果摘要，用于输出。
46	type importOutcome struct {
47		assetIDs []string
48		tickets  []ticketRemap
49	}
50	
51	func cmdImport(args []string, w io.Writer) error {
52		var opts cmdOptions
53		var sourceDir string
54		var assetIDs stringListFlag
55		fs := newFlagSet("import", &opts)
56		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
57		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
58		if err := parseFlags(fs, args); err != nil {
59			return err
60		}
61		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
62			return err
63		}
64		if len(assetIDs) == 0 {
65			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
66		}
67		for _, id := range assetIDs {
68			if id == "" {
69				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
70			}
71		}
72	
73		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
74		if err != nil {
75			return err
76		}
77		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
78		if len(outcome.tickets) == 0 {
79			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
80			return nil
81		}
82		fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
83		for _, m := range outcome.tickets {
84			fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
85		}
86		return nil
87	}
88	
89	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
90	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
91	// 两边原文件字节保持不变。
92	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
93		srcAbs, err := filepath.Abs(sourceDir)
94		if err != nil {
95			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
96		}
97		dstAbs, err := filepath.Abs(targetDir)
98		if err != nil {
99			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
100		}
101		if srcAbs == dstAbs {
102			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
103		}
104		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
105		srcPath := filepath.Join(srcAbs, dataFileName)
106		dstPath := filepath.Join(dstAbs, dataFileName)
107		if fi1, err1 := os.Stat(srcPath); err1 == nil {
108			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
109				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
110			}
111		}
112	
113		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
114		src, err := openSourceStore(srcAbs)
115		if err != nil {
116			return nil, err
117		}
118		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
119		dst, err := openStore(dstAbs)
120		if err != nil {
121			return nil, err
122		}
123		outcome, err := dst.mergeImport(src, assetIDs)
124		if err != nil {
125			return nil, err
126		}
127		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
128		if err := dst.save(); err != nil {
129			return nil, err
130		}
131		return outcome, nil
132	}
133	
134	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
135	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
136	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
137		// 重复编号按一项处理，保持首次出现的顺序。
138		selected := map[string]bool{}
139		ids := make([]string, 0, len(assetIDs))
140		for _, id := range assetIDs {
141			if !selected[id] {
142				selected[id] = true
143				ids = append(ids, id)
144			}
145		}
146		// 所选资产必须存在于源，且编号在目标中不存在。
147		assets := make([]*Asset, 0, len(ids))
148		for _, id := range ids {
149			a := src.findAsset(id)
150			if a == nil {
151				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
152			}
153			if s.findAsset(id) != nil {
154				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
155			}
156			assets = append(assets, a)
157		}
158		// 所选资产的全部工单，按源工单序号升序重新分配编号。
159		tickets := make([]*Ticket, 0)
160		for _, t := range src.data.Tickets {
161			if selected[t.AssetID] {
162				tickets = append(tickets, t)
163			}
164		}
165		sort.SliceStable(tickets, func(i, j int) bool {
166			ni, _ := parseTicketSeq(tickets[i].ID)
167			nj, _ := parseTicketSeq(tickets[j].ID)
168			return ni < nj
169		})
170		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
171		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
172			return nil, fmt.Errorf(
173				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
174				errConflict, s.data.NextTicketSeq, len(tickets))
175		}
176		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
177		srcReqByTicket := map[string]*requestBinding{}
178		for i := range src.data.Requests {
179			r := &src.data.Requests[i]
180			srcReqByTicket[r.TicketID] = r
181		}
182		for _, t := range tickets {
183			r := srcReqByTicket[t.ID]
184			if r == nil {
185				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
186			}
187			if s.findRequest(r.RequestID) != nil {
188				return nil, fmt.Errorf(
189					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
190			}
191		}
192		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
193		events := make([]Event, 0)
194		for _, e := range src.data.Events {
195			if selected[e.AssetID] {
196				events = append(events, e)
197			}
198		}
199		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
200		maxSeq := 0
201		for _, e := range s.data.Events {
202			if e.Seq > maxSeq {
203				maxSeq = e.Seq
204			}
205		}
206		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
207		if len(events) > math.MaxInt-maxSeq {
208			return nil, fmt.Errorf(
209				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
210				errConflict, maxSeq, len(events))
211		}
212	
213		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
214		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
215		for _, a := range assets {
216			na := *a
217			s.data.Assets = append(s.data.Assets, &na)
218		}
219		outcome := &importOutcome{assetIDs: ids}
220		remap := map[string]string{}
221		next := s.data.NextTicketSeq
222		for _, t := range tickets {
223			nt := *t
224			nt.ID = fmt.Sprintf("T%04d", next)
225			remap[t.ID] = nt.ID
226			s.data.Tickets = append(s.data.Tickets, &nt)
227			r := srcReqByTicket[t.ID]
228			s.data.Requests = append(s.data.Requests, requestBinding{
229				RequestID:   r.RequestID,
230				AssetID:     r.AssetID,
231				Description: r.Description,
232				TicketID:    nt.ID,
233			})
234			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
235			next++
236		}
237		s.data.NextTicketSeq = next
238		seq := maxSeq
239		for _, e := range events {
240			seq++
241			ne := e
242			ne.Seq = seq
243			ne.TicketID = remap[e.TicketID]
244			s.data.Events = append(s.data.Events, ne)
245		}
246		return outcome, nil
247	}
