// parseDate 解析 YYYY-MM-DD 形式的公历日期（0001 至 9999 年），返回日序号。
func parseDate(s string) (int64, error) {
    if len(s) != 10 || s[4] != '-' || s[7] != '-' {
        return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
    }
    y, ok1 := atoiN(s[0:4]); m, ok2 := atoiN(s[5:7]); d, ok3 := atoiN(s[8:10])
    if !ok1 || !ok2 || !ok3 {
        return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
    }
    if y < 1 || y > 9999 || m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m) {
        return 0, fmt.Errorf("不是 0001 至 9999 年间的有效公历日期: %q", s)
