    return daysFromCivil(y, m, d), nil
}

func atoiN(s string) (int, bool) {
    n := 0
    for i := 0; i < len(s); i++ {
        if s[i] < '0' || s[i] > '9' { return 0, false }
        n = n*10 + int(s[i]-'0')
