		if !ok {
			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
				e.AssetID, e.Seq)
		}
		derivedDue[e.AssetID] = formatDate(next)
